#!/usr/bin/env python3
"""
This program solves the 6‐house logic puzzle by searching for an assignment
of the 6 attributes – Name, Style, Lunch, Vacation, Height and Cigar – to 6 houses
(numbered 1 to 6) that satisfy all the given clues.
"""

import json
import sys

# All possible attribute values.
NAMES       = ['Arnold','Carol','Peter','Eric','Bob','Alice']
STYLES      = ['ranch','colonial','modern','craftsman','mediterranean','victorian']
LUNCHES     = ['pizza','stew','spaghetti','grilled cheese','stir fry','soup']
VACATIONS   = ['cultural','cruise','mountain','camping','city','beach']
HEIGHTS     = ['average','very tall','very short','short','tall','super tall']
CIGARS      = ['yellow monster','prince','dunhill','pall mall','blue master','blends']

# We represent each house as a dictionary with keys: Name, Style, Lunch, Vacation, Height, Cigar.
# Houses are in a list, index 0 corresponds to house1, index 1 to house2, etc.

def valid_constraint(solution):
    """
    Check (as completely as possible) that the partial (or full) assignment in
    list 'solution' (houses in order) does not violate any constraints.
    Only houses that have been assigned (solution list) are checked.
    """
    n = len(solution)
    # Helper: get house attribute at index i if exists.
    def get(i, key):
        if i < 0 or i >= len(solution):
            return None
        return solution[i].get(key)

    # 1. Alice is in the fifth house.
    if n >= 5:
        if solution[4].get('Name') != 'Alice':
            return False

    # 9. Eric is in the fourth house.
    if n >= 4:
        if solution[3].get('Name') != 'Eric':
            return False

    # Check each house's local conditions.
    for i, house in enumerate(solution):
        name = house.get('Name')
        style = house.get('Style')
        lunch = house.get('Lunch')
        vac   = house.get('Vacation')
        height= house.get('Height')
        cigar = house.get('Cigar')

        # 2. The person who loves stir fry is the person living in a colonial-style house.
        if lunch == 'stir fry' and style is not None and style != 'colonial':
            return False
        if style == 'colonial' and lunch is not None and lunch == 'stir fry':
            # OK; if style is colonial it doesn't force stir fry though clue 2 is one‐way.
            pass

        # 3. Alice loves spaghetti.
        if name == 'Alice' and lunch is not None and lunch != 'spaghetti':
            return False
        # 4. Arnold loves stew.
        if name == 'Arnold' and lunch is not None and lunch != 'stew':
            return False
        # 7. The person who has an average height is the person who loves stir fry.
        if height == 'average' and lunch is not None and lunch != 'stir fry':
            return False
        if lunch == 'stir fry' and height is not None and height != 'average':
            return False
        # 8. The person who loves beach vacations is the person in a ranch-style home.
        if vac == 'beach' and style is not None and style != 'ranch':
            return False
        if style == 'ranch' and vac is not None and vac != 'beach':
            return False
        # 11. The person who enjoys mountain retreats is the person who smokes Yellow Monster.
        if vac == 'mountain' and cigar is not None and cigar != 'yellow monster':
            return False
        if cigar == 'yellow monster' and vac is not None and vac != 'mountain':
            return False
        # 12. The person who enjoys mountain retreats is very tall.
        if vac == 'mountain' and height is not None and height != 'very tall':
            return False
        if height == 'very tall' and vac is not None and vac == 'mountain':
            pass  # Only one direction is required.
        # 14. The person who loves spaghetti is in a Victorian house.
        if lunch == 'spaghetti' and style is not None and style != 'victorian':
            return False
        # 15. The person who is tall is the person who loves beach vacations.
        if height == 'tall' and vac is not None and vac != 'beach':
            return False
        if vac == 'beach' and height is not None and height != 'tall':
            return False
        # 17. The person who loves stir fry is directly left of Bob.
        if lunch == 'stir fry':
            if i == len(solution)-1:
                # if this is the last house assigned, we can't check neighbor fully.
                pass
            else:
                next_name = solution[i+1].get('Name') if i+1 < n else None
                if next_name is not None and next_name != 'Bob':
                    return False
        # 23. The person who smokes blends is directly left of the person who smokes Blue Master.
        if cigar == 'blends':
            if i == len(solution)-1:
                pass
            else:
                next_cigar = solution[i+1].get('Cigar')
                if next_cigar is not None and next_cigar != 'blue master':
                    return False
        # 24. The person who goes on cultural tours is the person who is a pizza lover.
        if lunch == 'pizza' and vac is not None and vac != 'cultural':
            return False
        if vac == 'cultural' and lunch is not None and lunch != 'pizza':
            return False

    # Now check cross-house (relative position) constraints:
    # 5. There is one house between the person with average height and Peter.
    idx_avg = [i for i, h in enumerate(solution) if h.get('Height')=='average']
    idx_peter = [i for i, h in enumerate(solution) if h.get('Name')=='Peter']
    for i in idx_avg:
        for j in idx_peter:
            if abs(i - j) != 2:
                # If both are assigned and the condition fails, then error.
                # However, if multiple possibilities exist, we require that at least one pair satisfies?
                # Actually, there is exactly one average and one Peter.
                return False

    # 10. There is one house between the colonial house and the camping lover.
    idx_colonial = [i for i, h in enumerate(solution) if h.get('Style')=='colonial']
    idx_camping = [i for i, h in enumerate(solution) if h.get('Vacation')=='camping']
    if idx_colonial and idx_camping:
        for i in idx_colonial:
            for j in idx_camping:
                if abs(i - j) != 2:
                    return False

    # 13. The person who enjoys mountain retreats and the Dunhill smoker are next to each other.
    idx_mountain = [i for i, h in enumerate(solution) if h.get('Vacation')=='mountain']
    idx_dunhill  = [i for i, h in enumerate(solution) if h.get('Cigar')=='dunhill']
    if idx_mountain and idx_dunhill:
        valid_nei = False
        for i in idx_mountain:
            for j in idx_dunhill:
                if abs(i - j) == 1:
                    valid_nei = True
        if not valid_nei:
            return False

    # 16. The person who is tall is somewhere to the left of the person residing in a Victorian house.
    idx_tall = [i for i, h in enumerate(solution) if h.get('Height')=='tall']
    idx_vict = [i for i, h in enumerate(solution) if h.get('Style')=='victorian']
    if idx_tall and idx_vict:
        for i in idx_tall:
            for j in idx_vict:
                if i >= j:
                    return False

    # 18. The person in a modern-style house is somewhere to the left of Alice.
    idx_modern = [i for i, h in enumerate(solution) if h.get('Style')=='modern']
    idx_alice  = [i for i, h in enumerate(solution) if h.get('Name')=='Alice']
    if idx_modern and idx_alice:
        for i in idx_modern:
            for j in idx_alice:
                if i >= j:
                    return False

    # 19. The person in a Craftsman-style house is somewhere to the left of the person who is short.
    idx_craft = [i for i, h in enumerate(solution) if h.get('Style')=='craftsman']
    idx_short = [i for i, h in enumerate(solution) if h.get('Height')=='short']
    if idx_craft and idx_short:
        for i in idx_craft:
            for j in idx_short:
                if i >= j:
                    return False

    # 20. The person who loves stir fry is somewhere to the left of the Prince smoker.
    idx_stir = [i for i, h in enumerate(solution) if h.get('Lunch')=='stir fry']
    idx_prince = [i for i, h in enumerate(solution) if h.get('Cigar')=='prince']
    if idx_stir and idx_prince:
        for i in idx_stir:
            for j in idx_prince:
                if i >= j:
                    return False

    # 21. There are two houses between the person who loves grilled cheese and the person who is super tall.
    idx_gc = [i for i, h in enumerate(solution) if h.get('Lunch')=='grilled cheese']
    idx_super = [i for i, h in enumerate(solution) if h.get('Height')=='super tall']
    if idx_gc and idx_super:
        for i in idx_gc:
            for j in idx_super:
                if abs(i - j) != 3:
                    return False

    # 25. The person who is a pizza lover is somewhere to the left of the person who likes going on cruises.
    idx_pizza = [i for i, h in enumerate(solution) if h.get('Lunch')=='pizza']
    idx_cruise = [i for i, h in enumerate(solution) if h.get('Vacation')=='cruise']
    if idx_pizza and idx_cruise:
        for i in idx_pizza:
            for j in idx_cruise:
                if i >= j:
                    return False

    # Cross constraint 17: If a house has stir fry then its immediate right house (if exists) must be Bob.
    for i, h in enumerate(solution):
        if h.get('Lunch')=='stir fry':
            if i+1 < len(solution):
                if solution[i+1].get('Name') is not None and solution[i+1]['Name'] != 'Bob':
                    return False

    # Cross constraint 23: If a house smokes blends then the next house must smoke Blue Master.
    for i, h in enumerate(solution):
        if h.get('Cigar')=='blends':
            if i+1 < len(solution):
                if solution[i+1].get('Cigar') is not None and solution[i+1]['Cigar'] != 'blue master':
                    return False

    return True

def search(solution, used):
    """
    Recursive backtracking search.
    solution: list of houses (dictionaries) already assigned.
    used: a dictionary mapping attribute category to a set of values used so far.
    Attribute categories: 'Name','Style','Lunch','Vacation','Height','Cigar'
    """
    if len(solution) == 6:
        # When full solution, check overall constraints
        if valid_constraint(solution):
            return solution
        else:
            return None

    house_index = len(solution)
    # For house positions, we will try every possible combination for the 6 attributes
    for name in NAMES:
        if name in used['Name']:
            continue
        # Fixed positions: House5 (index 4) must be 'Alice'; House4 (index 3) must be 'Eric'.
        if house_index == 4 and name != 'Alice':
            continue
        if house_index == 3 and name != 'Eric':
            continue
        for style in STYLES:
            if style in used['Style']:
                continue
            # Constraint 6: Craftsman is not in the third house (index 2).
            if house_index == 2 and style == 'craftsman':
                continue
            for lunch in LUNCHES:
                if lunch in used['Lunch']:
                    continue
                for vac in VACATIONS:
                    if vac in used['Vacation']:
                        continue
                    for height in HEIGHTS:
                        if height in used['Height']:
                            continue
                        for cigar in CIGARS:
                            if cigar in used['Cigar']:
                                continue
                            # Build a candidate house.
                            house = {
                                'Name': name,
                                'Style': style,
                                'Lunch': lunch,
                                'Vacation': vac,
                                'Height': height,
                                'Cigar': cigar
                            }
                            # Append candidate and update used.
                            solution.append(house)
                            used['Name'].add(name)
                            used['Style'].add(style)
                            used['Lunch'].add(lunch)
                            used['Vacation'].add(vac)
                            used['Height'].add(height)
                            used['Cigar'].add(cigar)

                            if valid_constraint(solution):
                                result = search(solution, used)
                                if result is not None:
                                    return result

                            # Backtrack.
                            solution.pop()
                            used['Name'].remove(name)
                            used['Style'].remove(style)
                            used['Lunch'].remove(lunch)
                            used['Vacation'].remove(vac)
                            used['Height'].remove(height)
                            used['Cigar'].remove(cigar)
    return None

def main():
    # Initialize used sets for each category.
    used = {
        'Name': set(),
        'Style': set(),
        'Lunch': set(),
        'Vacation': set(),
        'Height': set(),
        'Cigar': set()
    }
    sol = search([], used)
    if sol is None:
        print("No solution found.", file=sys.stderr)
        sys.exit(1)
    # Prepare output in required JSON format.
    header = ["House", "Name", "Style", "Lunch", "Vacation", "Height", "Cigar"]
    rows = []
    # Houses are numbered 1 to 6.
    for i, house in enumerate(sol):
        row = [
            str(i+1),
            house['Name'],
            house['Style'],
            house['Lunch'],
            house['Vacation'],
            house['Height'],
            house['Cigar']
        ]
        rows.append(row)
    output = {"solution": {"header": header, "rows": rows}}
    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
